// Writes src/index.ts re-exporting every generated endpoint module, the models and the fetcher.
import { readdirSync, writeFileSync } from 'node:fs';

const root = new URL('../src/', import.meta.url);
const endpoints = readdirSync(new URL('generated/endpoints/', root), { withFileTypes: true })
  .filter((d) => d.isDirectory())
  .map((d) => d.name)
  .sort();
const lines = [
  '// Generated by scripts/write-index.mjs. Do not edit.',
  "export * from './fetcher';",
  ...endpoints.map((name) => `export * from './generated/endpoints/${name}/${name}';`),
  "export * from './generated/model';",
];
writeFileSync(new URL('index.ts', root), `${lines.join('\n')}\n`);
console.log(`index.ts: ${endpoints.length} endpoint modules`);
